 'export-menu':()=>showDialog('导出会议',`<div class="menu-list"><button data-action="export-md">${icon('note')}Markdown · 原文与人工纪要</button><button data-action="export-srt">${icon('clock')}SRT · 带时间戳的字幕</button></div>`),'export-md':()=>exportText('md'),'export-srt':()=>exportText('srt'),
 'meeting-menu':()=>showDialog('会议操作',`<div class="menu-list"><button data-action="edit-meeting">${icon('edit')}编辑会议信息</button><button data-action="context">${icon('note')}背景与关键词</button><button data-action="analyze">${icon('spark')}生成 / 更新分析</button><button data-action="media-files">${icon('project')}原始文件</button><button data-action="record">${icon('mic')}录制音频</button></div>`),'edit-meeting':editMeetingDialog,'context':()=>contextDialog(),'project-defaults':()=>contextDialog(true),'analyze':analyzeDialog,
 'media-files':()=>showDialog('原始文件',`<p>${current.fileName?esc(current.fileName):'这份示例资料仅包含人工测试转录，没有原始音视频。'}</p><div class="notice-line">${current.fileName?'导入的媒体保存在当前浏览器，可在这场会议中播放。备份导出不包含音视频文件。':'转录来源：会议项目内 fixtures/transcript.json。'}</div><div class="modal-actions">${btn('关闭','close-dialog','','btn-ghost')}${btn('导入音视频','import-media','upload')}</div>`),
